class Solution {
    public int lengthOfLongestSubstring(String s) {
        Map<Character, Integer> cnt = new HashMap<>();
        int res = 0;
        int start = 0;
        for (int end = 0; end < s.length(); end++) {
            if (cnt.containsKey(s.charAt(end))) {
                start = Math.max(start, cnt.get(s.charAt(end)));
                cnt.put(s.charAt(end), end + 1);
            } else {
                cnt.put(s.charAt(end), end + 1);
            }
            if (end - start +1> res)
                res = end - start + 1;
        }
        return res;

    }
}
